  example_vi,
  word_audio_url,
  sentence_audio_url
) as (
  values
    ('暧昧', '他们之间的关系一直暧昧不清，让人难以捉摸。', 'yêu đương, tình yêu, mập mờ', 'ài mèi', '他们之间的关系一直暧昧不清，让人难以捉摸。', 'yêu đương, tình yêu, mập mờ', 'ài mèi', 'Tāmen zhī jiān de guānxì yīzhí àimèi bù qīng, ràng rén nányǐ zhuōmō.', 'Mối quan hệ giữa họ luôn mập mờ khó hiểu, khiến người ta không thể đoán được.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-66e830b5690eef238b3fb6eb.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-d771aa99641221dc31faea9d.mp3'),
    ('爱戴', '老师深受同学们的爱戴和尊敬。', 'yêu thương, tình yêu thương', 'ài dài', '老师深受同学们的爱戴和尊敬。', 'yêu thương, tình yêu thương', 'ài dài', 'Lǎoshī shēn shòu tóngxuémen de àidài hé zūnjìng.', 'Thầy giáo rất được các học sinh yêu thương và kính trọng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-6c553b12d291abfad3a3d354.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-26c4f6d965df64a29c9884c7.mp3'),
