    ('不言而喻', '这个问题的严重性是不言而喻的。', 'rõ mồn một', 'bù yán ér yù', '这个问题的严重性是不言而喻的。', 'rõ mồn một', 'bù yán ér yù', 'Zhège wèntí de yánzhòng xìng shì bù yán ér yù de.', 'Tầm nghiêm trọng của vấn đề này là rõ mồn một.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-7d7889a002872f7e221a5208.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-900d30255f0f417dd6216f65.mp3'),
    ('不禁', '看到那么感人的电影，我不禁流下了眼泪。', 'không kiềm được', 'bù jīn', '看到那么感人的电影，我不禁流下了眼泪。', 'không kiềm được', 'bù jīn', 'Kàn dào nà me gǎn rén de diàn yǐng, wǒ bù jīn liú xià le yǎn lèi.', 'Xem bộ phim cảm động như vậy, tôi không kiềm được nước mắt.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-0941a43b705ae6afe1f960b1.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-c68df3dd09a929c1919a235d.mp3'),
    ('不相上下', '这两位选手的实力不相上下，比赛非常激烈。', 'ngang tài ngang sức', 'bù xiāng shàng xià', '这两位选手的实力不相上下，比赛非常激烈。', 'ngang tài ngang sức', 'bù xiāng shàng xià', 'Zhè liǎng wèi xuǎn shǒu de shí lì bù xiāng shàng xià, bǐ sài fēi cháng jī liè.', 'Thực lực của hai vận động viên này ngang tài ngang sức, cuộc thi rất căng thẳng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-9c3503551a180e1dbdf9d9cd.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-25810939840094cd05c33557.mp3'),
    ('不由得', '听到这个消息，他不由得感到惊讶。', 'đành phải', 'bù yóu dé', '听到这个消息，他不由得感到惊讶。', 'đành phải', 'bù yóu dé', 'Tīng dào zhè ge xiāo xī, tā bù yóu dé gǎn dào jīng yà.', 'Nghe tin này, anh ấy đành phải cảm thấy ngạc nhiên.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-c6bba9c1840cf12b2a3e1a45.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-f4a63f5bd335811e6f1f9c9f.mp3'),
    ('不止', '她的努力不止一次，终于获得了成功。', 'không chỉ (một lần )', 'bù zhǐ', '她的努力不止一次，终于获得了成功。', 'không chỉ (một lần )', 'bù zhǐ', 'Tā de nǔ lì bù zhǐ yī cì, zhōng yú huò dé le chéng gōng.', 'Nỗ lực của cô ấy không chỉ một lần, cuối cùng đã thành công.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-af25e2c748a326d963c8403b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-7afa9888ab29dc98e7536afa.mp3'),
    ('不时', '他上课时不时低头查看手机，非常注意信息。', 'đôi khi, thỉnh thoảng', 'bù shí', '他上课时不时低头查看手机，非常注意信息。', 'đôi khi, thỉnh thoảng', 'bù shí', 'Tā shàng kè shí bù shí dī tóu chá kàn shǒu jī, fēi cháng zhù yì xìn xī.', 'Anh ấy khi lên lớp thỉnh thoảng cúi đầu xem điện thoại, rất để ý tin nhắn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-e460867df21aaf8f89344d6d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-171ecde8c21406c8f915e4f5.mp3'),
    ('不料', '大家都认为他会赢，不料他却输掉了比赛。', 'không ngờ', 'bù liào', '大家都认为他会赢，不料他却输掉了比赛。', 'không ngờ', 'bù liào', 'Dà jiā dōu rèn wéi tā huì yíng, bù liào tā què shū diào le bǐ sài.', 'Mọi người đều nghĩ anh ấy sẽ thắng, không ngờ anh ấy lại thua trận.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-429f41177d7a70396e5f0073.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-3c1e6f6013fd8c284688bbbd.mp3'),
    ('不敢当', '您过奖了，我不敢当这么高的评价。', 'không dám', 'bù gǎn dāng', '您过奖了，我不敢当这么高的评价。', 'không dám', 'bù gǎn dāng', 'Nín guò jiǎng le, wǒ bù gǎn dāng zhè me gāo de píng jià.', 'Ông đã khen quá rồi, tôi không dám nhận sự đánh giá cao như vậy.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-031b91fdc5befc3d0d56770a.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-d612147e053f2a7ccc0f258c.mp3'),
    ('不择手段', '为了实现目标，他不择手段，甚至违反了法律。', 'không từ thủ đoạn', 'bù zé shǒu duàn', '为了实现目标，他不择手段，甚至违反了法律。', 'không từ thủ đoạn', 'bù zé shǒu duàn', 'Wèi le shí xiàn mù biāo, tā bù zé shǒu duàn, shèn zhì wéi fǎn le fǎ lǜ.', 'Để đạt được mục tiêu, anh ta không từ thủ đoạn, thậm chí phạm pháp.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-4a9ba6bf4ab3ad3e67692fee.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-ae4608e8c84ba20a9ccbcb94.mp3'),
    ('不愧', '她不愧是公司的顶梁柱，工作能力很强。', 'xứng đáng', 'bù kuì', '她不愧是公司的顶梁柱，工作能力很强。', 'xứng đáng', 'bù kuì', 'Tā bù kuì shì gōng sī de dǐng liáng zhù, gōng zuò néng lì hěn qiáng.', 'Cô ấy xứng đáng là trụ cột của công ty, khả năng làm việc rất mạnh.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-a39f2b06b1c438a9bab08682.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-a9dbf3ee1bbc0aa075456715.mp3'),
    ('不惜', '为了梦想，他不惜一切代价去努力奋斗。', 'không tiếc', 'bù xī', '为了梦想，他不惜一切代价去努力奋斗。', 'không tiếc', 'bù xī', 'Wèi le mèng xiǎng, tā bù xī yī qiè dài jià qù nǔ lì fèn dòu.', 'Vì ước mơ, anh ấy không tiếc mọi giá để cố gắng phấn đấu.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-de1e6d53c1f135d27c6036b2.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-49a6e7e4f6b4c85c2be85059.mp3'),
    ('不得已', '天气太糟糕，我们不得已取消了旅行计划。', 'bất đắc dĩ', 'bù dé yǐ', '天气太糟糕，我们不得已取消了旅行计划。', 'bất đắc dĩ', 'bù dé yǐ', 'Tiān qì tài zāo gāo, wǒ men bù dé yǐ qǔ xiāo le lǚ xíng jì huà.', 'Thời tiết quá tệ, chúng tôi bất đắc dĩ phải hủy kế hoạch du lịch.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-353c950544d93dced0afea06.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-70c9275b75dd87b63690d537.mp3'),
    ('不屑一顾', '对于那些无理的批评，他根本不屑一顾。', 'không đáng quan tâm', 'bù xiè yī gù', '对于那些无理的批评，他根本不屑一顾。', 'không đáng quan tâm', 'bù xiè yī gù', 'Duì yú nà xiē wú lǐ de pī píng, tā gēn běn bù xiè yī gù.', 'Với những lời phê bình vô lý đó, anh ấy hoàn toàn không đáng quan tâm.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-bbd6b8313c82df70480a169b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-b5fc5d743b4ab426275a9e70.mp3'),
    ('不妨', '天气这么好，我们不妨去郊游放松一下。', 'đừng ngại', 'bù fáng', '天气这么好，我们不妨去郊游放松一下。', 'đừng ngại', 'bù fáng', 'Tiān qì zhè me hǎo, wǒ men bù fáng qù jiāo yóu fàng sōng yī xià.', 'Thời tiết đẹp như thế, chúng ta đừng ngại đi dã ngoại thư giãn một chút.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-36272e395f804636bfa85c72.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-ca47dd19e046749f5630e9a6.mp3'),
    ('不堪', '连续的加班让我感到疲惫不堪，必须休息。', 'quá mức chịu đựng', 'bù kān', '连续的加班让我感到疲惫不堪，必须休息。', 'quá mức chịu đựng', 'bù kān', 'Lián xù de jiā bān ràng wǒ gǎn dào pí bèi bù kān, bì xū xiū xī.', 'Làm thêm giờ liên tiếp khiến tôi cảm thấy mệt mỏi quá mức chịu đựng, phải nghỉ ngơi.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-dbcf9e5f3c57abd2371daa24.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-d3a954e748459e62a77bc990.mp3'),
    ('不可思议', '他突然的成功真是不可思议，让人难以相信。', 'không thể tưởng tượng nổi', 'bù kě sī yì', '他突然的成功真是不可思议，让人难以相信。', 'không thể tưởng tượng nổi', 'bù kě sī yì', 'Tā tú rán de chéng gōng zhēn shì bù kě sī yì, ràng rén nán yǐ xiāng xìn.', 'Thành công đột ngột của anh ấy thật không thể tưởng tượng nổi, khiến người ta khó tin.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-35b7e08321e233046392213d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-2f32fa0138ffa22d16d73c9c.mp3'),
    ('不免', '遇到困难时，我们不免会感到失落和沮丧。', 'không tránh khỏi', 'bù miǎn', '遇到困难时，我们不免会感到失落和沮丧。', 'không tránh khỏi', 'bù miǎn', 'Yù dào kùn nán shí, wǒ men bù miǎn huì gǎn dào shī luò hé jǔ sàng.', 'Khi gặp khó khăn, chúng ta không tránh khỏi cảm thấy thất vọng và chán nản.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-8f26ce2c892e1aeb4542b863.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-697c795db2673bfa211b4d8f.mp3'),
    ('不像话', '他的行为真是太不像话了，大家都很生气。', 'chẳng ra làm sao cả', 'bù xiàng huà', '他的行为真是太不像话了，大家都很生气。', 'chẳng ra làm sao cả', 'bù xiàng huà', 'Tā de xíng wéi zhēn shì tài bù xiàng huà le, dà jiā dōu hěn shēng qì.', 'Hành động của anh ta thật chẳng ra làm sao cả, mọi người đều rất tức giận.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-baf08af9464b91485201f6af.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-818d0b3cbed226474b418ba8.mp3'),
    ('馋', '我一看到美食就馋得流口水，根本控制不住自己。', 'thèm, ham', 'chán', '我一看到美食就馋得流口水，根本控制不住自己。', 'thèm, ham', 'chán', 'Wǒ yī kàn dào měi shí jiù chán de liú kǒu shuǐ, gēn běn kòng zhì bù zhù zì jǐ.', 'Tôi cứ nhìn thấy đồ ăn ngon thì thèm chảy nước miếng, hoàn toàn không kiểm soát được bản thân.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-3681b9dfa89e9d495a326bc4.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-6ecbd892ee112dda0005a9bb.mp3'),
    ('颤抖', '寒冷的天气使他的手不停地颤抖。', 'run rẩy', 'chàn dǒu', '寒冷的天气使他的手不停地颤抖。', 'run rẩy', 'chàn dǒu', 'Hán lěng de tiān qì shǐ tā de shǒu bù tíng de chàn dǒu.', 'Thời tiết lạnh khiến tay anh ấy run rẩy không ngừng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-e098dab483a83b415e2235d9.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-fb05aba6ce70bc4df4c1866c.mp3'),
    ('雌雄', '这场比赛双方势均力敌，真正体现了雌雄对决。', 'thắng bại, sống mái', 'cí xióng', '这场比赛双方势均力敌，真正体现了雌雄对决。', 'thắng bại, sống mái', 'cí xióng', 'Zhè chǎng bǐ sài shuāng fāng shì jūn lì dí, zhēn zhèng tǐ xiàn le cí xióng duì jué.', 'Trận đấu này hai bên ngang sức ngang tài, thực sự thể hiện cuộc sống mái thắng bại.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-cbedfc07ba43df867188d079.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-d3230b43f794524f54c6eb3b.mp3'),
    ('除', '数学题里面，必须先做加法再做除法。', 'trừ, chia (phép tính)', 'chú', '数学题里面，必须先做加法再做除法。', 'trừ, chia (phép tính)', 'chú', 'shù xué tí lǐ miàn, bì xū xiān zuò jiā fǎ zài zuò chú fǎ.', 'Trong bài toán, phải làm phép cộng trước rồi mới làm phép chia.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-d213ae206e7e7c07f288c15e.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-e0cc7c53b9858b45ac70ca39.mp3'),
    ('陈述', '他在会议上详细陈述了项目的进展情况。', 'tường trình, trần thuật', 'chén shù', '他在会议上详细陈述了项目的进展情况。', 'tường trình, trần thuật', 'chén shù', 'tā zài huì yì shàng xiáng xì chén shù le xiàng mù de jìn zhǎn qíng kuàng.', 'Anh ấy đã trình bày chi tiết tiến độ dự án tại cuộc họp.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-c73274206af76fb0be2e2f64.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-7e93b528b85ecdd112e6bdc4.mp3'),
    ('陈旧', '这种陈旧的思想已经不适合现代社会的发展。', 'lỗi thời, cũ kĩ', 'chén jiù', '这种陈旧的思想已经不适合现代社会的发展。', 'lỗi thời, cũ kĩ', 'chén jiù', 'zhè zhǒng chén jiù de sī xiǎng yǐ jīng bù shì hé xiàn dài shè huì de fā zhǎn.', 'Tư tưởng lỗi thời này không còn phù hợp với sự phát triển xã hội hiện đại.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-fb24792a954ec6d0e5b167cb.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-52d3ae95d25df5543b2eb6b7.mp3'),
    ('陈列', '博物馆里陈列着许多珍贵的历史文物。', 'trưng bày, bày', 'chén liè', '博物馆里陈列着许多珍贵的历史文物。', 'trưng bày, bày', 'chén liè', 'bó wù guǎn lǐ chén liè zhe xǔ duō zhēn guì de lì shǐ wén wù.', 'Trong bảo tàng được trưng bày nhiều cổ vật lịch sử quý giá.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-39f6fa978a4ead27c322cab1.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-a956a06fefe6186d892118eb.mp3'),
    ('阐述', '专家在讲座中阐述了人工智能的未来趋势。', 'trình bày', 'chǎn shù', '专家在讲座中阐述了人工智能的未来趋势。', 'trình bày', 'chǎn shù', 'zhuān jiā zài jiǎng zuò zhōng chǎn shù le rén gōng zhì néng de wèi lái qū shì.', 'Chuyên gia đã trình bày về xu hướng tương lai của trí tuệ nhân tạo trong buổi thuyết trình.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-dd8672fb49f00758d93281a4.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-f60856f4cb511d8a61e3b1cd.mp3'),
    ('锤', '工人用锤子敲打着铁钉。', 'cái búa', 'chuí', '工人用锤子敲打着铁钉。', 'cái búa', 'chuí', 'gōng rén yòng chuí zi qiāo dǎ zhe tiě dīng.', 'Công nhân đang dùng cái búa đóng đinh sắt.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-88ae2acee5526d96fb919a58.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-1a737973b83d83cd04353d69.mp3'),
    ('钞票', '他从钱包里拿出几张钞票支付了账单。', 'tờ tiền', 'chāo piào', '他从钱包里拿出几张钞票支付了账单。', 'tờ tiền', 'chāo piào', 'tā cóng qián bāo lǐ ná chū jǐ zhāng chāo piào zhī fù le zhàng dān.', 'Anh ấy lấy vài tờ tiền từ ví ra để trả hóa đơn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-44c2fa737c45998c035096e6.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-bd066dcdb567d44cd0b99534.mp3'),
    ('重叠', '这两个声音在录音中重叠，导致听起来很混乱。', 'lặp lại', 'chóng dié', '这两个声音在录音中重叠，导致听起来很混乱。', 'lặp lại', 'chóng dié', 'zhè liǎng gè shēng yīn zài lù yīn zhōng chóng dié, dǎo zhì tīng qǐ lái hěn hùn luàn.', 'Hai âm thanh này chồng lên nhau trong bản thu, làm cho nghe rất lộn xộn.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-24181de0e20037f033b6e767.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-0d0c85eefc4ee175e8185b9c.mp3'),
    ('采集', '科研人员采集了不同地区的植物样本进行分析。', 'hái lượm, thu thập', 'cǎi jí', '科研人员采集了不同地区的植物样本进行分析。', 'hái lượm, thu thập', 'cǎi jí', 'kē yán rén yuán cǎi jí le bù tóng dì qū de zhí wù yàng běn jìn xíng fēn xī.', 'Nhân viên nghiên cứu đã thu thập mẫu thực vật từ các vùng khác nhau để phân tích.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-6a0ae77f8d9c3cbd8de6ecb0.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-faf6ca8980f9e30cc2c30de2.mp3'),
    ('采购', '公司最近增加了办公设备的采购预算。', 'mua, thu mua', 'cǎi gòu', '公司最近增加了办公设备的采购预算。', 'mua, thu mua', 'cǎi gòu', 'gōng sī zuì jìn zēng jiā le bàn gōng shè bèi de cǎi gòu yù suàn.', 'Công ty gần đây đã tăng ngân sách mua sắm thiết bị văn phòng.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-6e098153a5860b461caae778.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-bee14e1096e0b9f4ba5718f3.mp3'),
    ('采纳', '经理采纳了员工提出的建议来改善工作流程。', 'tiếp nhận, tiếp thu', 'cǎi nà', '经理采纳了员工提出的建议来改善工作流程。', 'tiếp nhận, tiếp thu', 'cǎi nà', 'jīng lǐ cǎi nà le yuán gōng tí chū de jiàn yì lái gǎi shàn gōng zuò liú chéng.', 'Quản lý đã tiếp thu đề xuất của nhân viên để cải thiện quy trình làm việc.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-93135b1b30daec7887942c8b.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-76935cbc565a3f04cdf6fea0.mp3'),
    ('迟钝', '由于疲劳，他的反应迟钝，做事效率低下。', 'chậm chạp (hành động, phản ứng, hoạt động)', 'chí dùn', '由于疲劳，他的反应迟钝，做事效率低下。', 'chậm chạp (hành động, phản ứng, hoạt động)', 'chí dùn', 'yóu yú pí láo, tā de fǎn yìng chí dùn, zuò shì xiào lǜ dī xià.', 'Do mệt mỏi, phản ứng của anh ấy chậm chạp, hiệu quả làm việc thấp.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-a5dfed582cae2fa48dbbd3d7.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-55b467320228723081b239eb.mp3'),
    ('迟缓', '交通事故导致救援行动进行得非常迟缓。', 'chậm, chậm lại', 'chí huǎn', '交通事故导致救援行动进行得非常迟缓。', 'chậm, chậm lại', 'chí huǎn', 'jiāo tōng shì gù dǎo zhì jiù yuán xíng dòng jìn xíng dé fēi cháng chí huǎn.', 'Tai nạn giao thông khiến hoạt động cứu hộ tiến hành rất chậm chạp.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-3c15cc95f8c7adc10408934c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-fb6ea0677d615de55d659062.mp3'),
    ('迟疑', '她在回答问题时表现出明显的迟疑和不确定。', 'lưỡng lự', 'chí yí', '她在回答问题时表现出明显的迟疑和不确定。', 'lưỡng lự', 'chí yí', 'tā zài huí dá wèn tí shí biǎo xiàn chū míng xiǎn de chí yí hé bù què dìng.', 'Cô ấy thể hiện sự lưỡng lự và không chắc chắn rõ ràng khi trả lời câu hỏi.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-51c9020bf8f2569757f726b4.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-2f0113f539bfbb9d9ef6aa44.mp3'),
    ('超越', '这位运动员努力训练，终于超越了自己的极限。', 'vượt qua, vượt (đối thủ, thời gian, tuổi tác, thành tựu)', 'chāo yuè', '这位运动员努力训练，终于超越了自己的极限。', 'vượt qua, vượt (đối thủ, thời gian, tuổi tác, thành tựu)', 'chāo yuè', 'zhè wèi yùn dòng yuán nǔ lì xùn liàn, zhōng yú chāo yuè le zì jǐ de jí xiàn.', 'Vận động viên này đã luyện tập chăm chỉ và cuối cùng vượt qua giới hạn của bản thân.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-21f234b3c51edeb2f4607985.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-9eb763ca8aa7c327ec03d089.mp3'),
    ('赤道', '赤道附近的气候通常炎热而潮湿。', 'xích đạo', 'chì dào', '赤道附近的气候通常炎热而潮湿。', 'xích đạo', 'chì dào', 'chì dào fù jìn de qì hòu tōng cháng yán rè ér cháo shī.', 'Khí hậu gần đường xích đạo thường nóng ẩm.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-423fa0708d09a58455ee868c.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-3554bdaa7a0873ba1fb7bd8a.mp3'),
    ('赤字', '政府为了减少财政赤字，采取了多项紧缩措施。', 'bội chi', 'chì zì', '政府为了减少财政赤字，采取了多项紧缩措施。', 'bội chi', 'chì zì', 'zhèng fǔ wèi le jiǎn shǎo cái zhèng chì zì, cǎi qǔ le duō xiàng jǐn suō cuò shī.', 'Chính phủ đã áp dụng nhiều biện pháp thắt chặt để giảm thâm hụt tài chính.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-7865b21012629320e3b14086.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-c59aa089a505b8ce8c069737.mp3'),
    ('财政', '财政政策的调整直接影响国家经济的发展。', 'tài chính', 'cái zhèng', '财政政策的调整直接影响国家经济的发展。', 'tài chính', 'cái zhèng', 'cái zhèng zhèng cè de tiáo zhěng zhí jiē yǐng xiǎng guó jiā jīng jì de fā zhǎn.', 'Điều chỉnh chính sách tài chính ảnh hưởng trực tiếp đến sự phát triển kinh tế quốc gia.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-f69c325544a29bfecaf27e63.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-33a603caf62fd11a2088bff3.mp3'),
    ('财富', '科技创新是一个国家财富增长的重要动力。', 'tài sản, sự giàu có', 'cái fù', '科技创新是一个国家财富增长的重要动力。', 'tài sản, sự giàu có', 'cái fù', 'kē jì chuàng xīn shì yí gè guó jiā cái fù zēng zhǎng de zhòng yào dòng lì.', 'Đổi mới công nghệ là động lực quan trọng cho sự gia tăng tài sản của một quốc gia.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-8610e9b28806423c794ed83d.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-f524215502d66cafeaee88fe.mp3'),
    ('财务', '公司的财务部门负责监督所有的账目和报表。', 'tài vụ', 'cái wù', '公司的财务部门负责监督所有的账目和报表。', 'tài vụ', 'cái wù', 'gōng sī de cái wù bù mén fù zé jiān dū suǒ yǒu de zhàng mù hé bào biǎo.', 'Bộ phận tài vụ của công ty chịu trách nhiệm giám sát tất cả các sổ sách và báo cáo.', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/word-506c068a2a1eb95aabf52a2a.mp3', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/hsk6-co-ban/sentence-55ea743a5db58e75188ecd8c.mp3')
)
update public.cards as card
set
  pinyin = case
    when card.pinyin = repaired.original_pinyin then repaired.pinyin
    else card.pinyin
  end,
  meaning_vi = case
    when card.meaning_vi = repaired.original_meaning_vi then repaired.meaning_vi
    else card.meaning_vi
  end,
  example_cn = repaired.example_cn,
  example_pinyin = repaired.example_pinyin,
  example_vi = repaired.example_vi,
  word_audio_url = repaired.word_audio_url,
  sentence_audio_url = repaired.sentence_audio_url
from public.decks as deck,
  repaired_hsk as repaired
where card.deck_id = deck.id
  and card.user_id = deck.user_id
  and (
    deck.source_template_slug = 'hsk6-co-ban'
    or (
      deck.source_template_slug is null
      and deck.name = 'HSK6 cơ bản'
    )
  )
  and card.chinese = repaired.chinese
  and (
    card.example_cn is not distinct from repaired.original_example_cn
    or card.example_cn is null
  );
